/**
 * The tile grid's built-in pixel font: printable ASCII (0x20–0x7E), 8×8 each.
 *
 * Baked from "Press Start 2P" by CodeMan38 (SIL Open Font License 1.1,
 * https://fonts.google.com/specimen/Press+Start+2P), rasterised on its native
 * 8-pixel grid. Baked rather than loaded so the grid renders identically on
 * every device, with no font request and no anti-aliasing.
 *
 * Each glyph is 16 hex digits: eight rows, one byte per row, MSB = leftmost.
 */
const PIXEL_FONT_HEX =
  '';

const FIRST = 0x20;
const LAST = 0x7e;

/** 8×8 bitmap for a character as an array of 8 row bytes, or null if not in the font. */
export function pixelGlyph(ch) {
  const code = ch.codePointAt(0);
  if (code < FIRST || code > LAST) return null;
  const at = (code - FIRST) * 16;
  const rows = [];
  for (let y = 0; y < 8; y++) rows.push(parseInt(PIXEL_FONT_HEX.substr(at + y * 2, 2), 16));
  return rows;
}
